  it('composed path is idempotent', () => {
    const input = ['/**', ' * @copyright 2026 Joe Huss <detain@interserver.net>', ' */', 'export const x = 1;'].join('\n');
    expect(processTsFile(input)).toBeNull();
  });

  it('prependTsDocblock adds copyright after shebang', () => {
