  --tracking-wide:   0.04em;
  --tracking-caps:   0.12em;
  --leading-tight:   1.1;
  --leading-snug:    1.3;
  --leading-normal:  1.55;
  --leading-relaxed: 1.7;
}

.numeric {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-feature-settings: 'tnum' 1;
}
.eyebrow {
  font-size: var(--text-2xs);
  font-weight: var(--font-semibold);
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  color: var(--text-subtle);
}

@import './colors.css';
@import './spacing.css';
@import './typography.css';
@import './radius.css';
@import './shadow.css';
@import './motion.css';
@import './density.css';

*, *::before, *::after {
    box-sizing: border-box;
}

* {
    margin: 0;
}

html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-optical-sizing: auto;
}

body {
    font-family: var(--font-sans);
    font-size: var(--text-base);
    background-color: var(--color-bg);
    color: var(--color-text);
    line-height: var(--leading-normal);
    letter-spacing: var(--tracking-snug);
}

img, picture, video, canvas, svg {
    display: block;
    max-width: 100%;
}

input, button, textarea, select {
    font: inherit;
}

p, h1, h2, h3, h4, h5, h6 {
    overflow-wrap: break-word;
}

a {
    color: inherit;
    text-decoration: none;
}

button {
    cursor: pointer;
    border: none;
    background: none;
}

ul, ol {
    list-style: none;
    padding: 0;
}

html[data-reduced-motion='true'] *,
html[data-reduced-motion='true'] *::before,
html[data-reduced-motion='true'] *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
}

:root,
[data-theme='nocturne'] {
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.45);
  --shadow-2: 0 4px 14px rgba(0, 0, 0, 0.48);
  --shadow-3: 0 14px 36px rgba(0, 0, 0, 0.55);
  --shadow-4: 0 28px 64px -16px rgba(0, 0, 0, 0.72);
  --glow-amber: 0 0 0 1px rgba(245, 165, 36, 0.35), 0 10px 36px -8px rgba(245, 165, 36, 0.40);

  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-4);
}

[data-theme='daylight'] {
  --shadow-1: 0 1px 2px rgba(74, 55, 20, 0.10);
  --shadow-2: 0 4px 14px rgba(74, 55, 20, 0.12);
  --shadow-3: 0 14px 36px rgba(74, 55, 20, 0.16);
  --shadow-4: 0 28px 64px -16px rgba(74, 55, 20, 0.24);
  --glow-amber: 0 0 0 1px rgba(217, 130, 9, 0.30), 0 10px 36px -8px rgba(245, 165, 36, 0.35);

  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-4);
}

[data-theme='midnight'] {
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.70);
  --shadow-2: 0 4px 14px rgba(0, 0, 0, 0.70);
  --shadow-3: 0 14px 36px rgba(0, 0, 0, 0.80);
  --shadow-4: 0 28px 64px -16px rgba(0, 0, 0, 0.90);
  --glow-amber: 0 0 0 1px rgba(245, 165, 36, 0.40), 0 10px 36px -8px rgba(245, 165, 36, 0.45);

  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-4);
}

:root {
    --space-0: 0;
    --space-1: 0.25rem;
    --space-2: 0.5rem;
    --space-3: 0.75rem;
    --space-4: 1rem;
    --space-5: 1.25rem;
    --space-6: 1.5rem;
    --space-8: 2rem;
    --space-10: 2.5rem;
    --space-12: 3rem;
    --space-16: 4rem;
    --space-20: 5rem;
    --space-24: 6rem;
}
